 if(game&&type==='damageReset'){if(game.s.pendingDecision)game.s.pendingDecision.chosen=[];persist();decisionDialog();return;}
 if(game&&type==='damageConfirm'){const before=game.s.active,wasAI=game.isAI();if(game.confirmDamage()){modal.close();afterAction(before,wasAI);}return;}
