  const slot=Number(el.dataset.slot),castId=Number(el.value),old=cfg.roster[slot];
  const other=cfg.roster.indexOf(castId);
  if(other>=0)cfg.roster[other]=old;
  cfg.roster[slot]=castId;setup();
